// Block (composition) — in-page navigation for editorial headings.
// Link owns interaction and typography; Stack owns the vertical flow.
import type { CSSProperties, Ref } from "react";
import { Link } from "../components/Link";
import { Stack } from "../layouts/Stack";
import "./TableOfContents.css";

export interface TableOfContentsProps {
  /** Anchor targets in document order. */
  items: {
    id: string;
    label: string;
    level?: number;
  }[];
  /** ID of the section currently being read. */
  activeId?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function TableOfContents({
  items,
  activeId,
  className,
  ref,
}: TableOfContentsProps) {
  return (
    <Stack
      as="nav"
      ref={ref}
      aria-label="Table of contents"
      gap="x-small"
      className={className ? `sd-tableofcontents ${className}` : "sd-tableofcontents"}
    >
      {items.map((item) => {
        const level = Math.max(1, item.level ?? 1);
        return (
          <Link
            key={item.id}
            variant="quiet"
            href={`#${item.id}`}
            aria-current={activeId === item.id ? "true" : undefined}
            data-level={level}
            className="sd-tableofcontents__link sd-type-label-medium"
            style={{ "--sd-layout-toc-depth": level - 1 } as CSSProperties}
          >
            {item.label}
          </Link>
        );
      })}
    </Stack>
  );
}

/* TableOfContents.css — .sd-tableofcontents (Block)
   Arrangement only: fills the available navigation column. A top-level link starts on the content
   edge (component-contract.md §6 rule 8) and each heading level below the first steps in one space
   rung; the depth arrives inline as a local intermediate, not a token. */
.sd-tableofcontents {
  width: 100%;
}

.sd-tableofcontents__link {
  --sd-layout-toc-depth: initial;
  display: block;
  margin-inline-start: calc(var(--sd-layout-toc-depth, 0) * var(--sd-space-medium));
}
